        "title": "Consultation - CMC abou moussiliou (Enregistré automatiquement)",
        "templateId": "rapport_cs_assurance",
        "patientNom": "CMC",
        "patientPrenom": "abou moussiliou (Enregistré automatiquement)",
        "patientAge": "46 ans",
        "date": "2020-01-28",
        "diagnosis": "",
