        "title": "Consultation - CM dossa colbert",
        "templateId": "rapport_cs_assurance",
        "patientNom": "CM",
        "patientPrenom": "dossa colbert",
        "patientAge": "39 ans",
        "date": "2024-02-15",
        "diagnosis": "",
